import {Text, View} from '@tarojs/components'
import {useEffect, useMemo, useRef} from 'react'
import {Animated, Easing, StyleSheet} from 'react-native'
import SvgIcon, {Path} from 'react-native-svg'
import type {CreateGenerationState} from '../types'
import CreateBackdrop from './CreateBackdrop'

const CARD_WIDTH = 166
const CARD_HEIGHT = 222
const DETAIL_ITEM_HEIGHT = 42

interface AnalysisStageProps {
  state: CreateGenerationState
  topInset: number
  bottomInset: number
  onCancelGeneration: () => void
}

function SparkleGlyph() {
  return (
    <SvgIcon width='42' height='42' viewBox='0 0 42 42' fill='none'>
      <Path
        d='M21 8.8C21.52 13.76 23.31 17.58 28.2 18.75C23.31 19.92 21.52 23.74 21 28.7C20.48 23.74 18.69 19.92 13.8 18.75C18.69 17.58 20.48 13.76 21 8.8Z'
        fill='#FCFCFC'
      />
      <Path
        d='M30.8 13.4C31.1 16.06 32.13 18.1 34.76 18.72C32.13 19.35 31.1 21.38 30.8 24.05C30.5 21.38 29.47 19.35 26.84 18.72C29.47 18.1 30.5 16.06 30.8 13.4Z'
        fill='#FCFCFC'
        fillOpacity='0.8'
      />
    </SvgIcon>
  )
}

export default function AnalysisStage({
  state,
  topInset,
  bottomInset,
  onCancelGeneration,
}: AnalysisStageProps) {
  const introProgress = useRef(new Animated.Value(0)).current
  const cardSpin = useRef(new Animated.Value(0)).current
  const detailTranslateY = useRef(new Animated.Value(0)).current
  const spinAnimationRef = useRef<Animated.CompositeAnimation | null>(null)
  const spinDelayRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const detailTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const detailAnimationRef = useRef<Animated.CompositeAnimation | null>(null)
  const detailItems = useMemo(
    () =>
      state.detailItems.length > 1
        ? [...state.detailItems, state.detailItems[0]]
        : state.detailItems,
    [state.detailItems],
  )

  useEffect(() => {
    introProgress.setValue(0)
    cardSpin.setValue(0)
    detailTranslateY.setValue(0)

    Animated.timing(introProgress, {
      toValue: 1,
      duration: 560,
      easing: Easing.out(Easing.cubic),
      useNativeDriver: true,
    }).start()

    spinDelayRef.current = setTimeout(() => {
      spinAnimationRef.current = Animated.loop(
        Animated.timing(cardSpin, {
          toValue: 1,
          duration: 2600,
          easing: Easing.linear,
          useNativeDriver: true,
        }),
      )
      spinAnimationRef.current.start()
    }, 420)

    if (state.detailItems.length > 1) {
      let activeIndex = 0

      const queueDetailRoll = () => {
        detailTimerRef.current = setTimeout(() => {
          const nextIndex = activeIndex + 1

          detailAnimationRef.current = Animated.timing(detailTranslateY, {
            toValue: -nextIndex * DETAIL_ITEM_HEIGHT,
            duration: 460,
            easing: Easing.out(Easing.cubic),
            useNativeDriver: true,
          })

          detailAnimationRef.current.start(({finished}) => {
            if (!finished) {
              return
            }

            activeIndex = nextIndex

            if (activeIndex === state.detailItems.length) {
              activeIndex = 0
              detailTranslateY.setValue(0)
            }

            queueDetailRoll()
          })
        }, 1500)
      }

      detailTimerRef.current = setTimeout(queueDetailRoll, 900)
    }

    return () => {
      if (spinDelayRef.current) {
        clearTimeout(spinDelayRef.current)
      }
      if (detailTimerRef.current) {
        clearTimeout(detailTimerRef.current)
      }
      spinAnimationRef.current?.stop?.()
      detailAnimationRef.current?.stop?.()
    }
  }, [cardSpin, detailTranslateY, introProgress, state.detailItems])

  const cardAnimatedStyle = {
    opacity: introProgress.interpolate({
      inputRange: [0, 0.16, 1],
      outputRange: [0, 1, 1],
    }),
    transform: [
      {
        translateY: introProgress.interpolate({
          inputRange: [0, 1],
          outputRange: [112, 0],
        }),
      },
      {
        scale: introProgress.interpolate({
          inputRange: [0, 1],
          outputRange: [1.82, 1],
        }),
      },
    ],
  }

  const cardSpinAnimatedStyle = {
    transform: [
      {perspective: 1100},
      {
        rotateY: cardSpin.interpolate({
          inputRange: [0, 1],
          outputRange: ['0deg', '360deg'],
        }),
      },
    ],
  }

  const copyAnimatedStyle = {
    opacity: introProgress.interpolate({
      inputRange: [0, 0.45, 1],
      outputRange: [0, 0, 1],
    }),
    transform: [
      {
        translateY: introProgress.interpolate({
          inputRange: [0, 1],
          outputRange: [26, 0],
        }),
      },
    ],
  }

  return (
    <View
      style={[
        styles.overlay,
        {
          paddingTop: topInset + 10,
          paddingBottom: Math.max(bottomInset, 22),
        },
      ] as any}
      data-testid='create-analysis-stage'
    >
      <CreateBackdrop variant='warm' />
      <View pointerEvents='none' style={styles.overlayGlow} />

      <View style={styles.content}>
        <Animated.View style={[styles.cardStage, cardAnimatedStyle] as any}>
          <Animated.View style={[styles.cardSpinShell, cardSpinAnimatedStyle] as any}>
            <View style={[styles.cardFace, styles.cardFront] as any}>
              <View style={styles.cardHardware}>
                <View style={styles.cardHardwareSlot} />
              </View>
              <View style={styles.frontBadge}>
                <Text style={styles.frontBadgeText}>{state.monogram}</Text>
              </View>
              <View style={styles.frontPrimaryBar} />
              <View style={styles.frontSecondaryBar} />
            </View>

            <View style={[styles.cardFace, styles.cardBack] as any}>
              <View style={styles.cardHardware}>
                <View style={[styles.cardHardwareSlot, styles.cardHardwareSlotBack] as any} />
              </View>
              <View style={styles.backBadge}>
                <SparkleGlyph />
              </View>
              <View style={[styles.backPrimaryBar, styles.backBarShared] as any} />
              <View style={[styles.backSecondaryBar, styles.backBarShared] as any} />
            </View>
          </Animated.View>
        </Animated.View>

        <Animated.View style={[styles.copyBlock, copyAnimatedStyle] as any}>
          <View style={styles.titleRow}>
            <Text style={styles.titleLead}>正在分析</Text>
            <View style={styles.detailViewport}>
              <Animated.View
                style={[
                  styles.detailTrack,
                  {transform: [{translateY: detailTranslateY}]},
                ] as any}
              >
                {detailItems.map((item, index) => (
                  <View key={`${item}-${index}`} style={styles.detailItem}>
                    <Text style={styles.titleDetail}>{item}</Text>
                  </View>
                ))}
              </Animated.View>
            </View>
          </View>

          <Text style={styles.subtitle}>正在为你的目标岗位量身定做最佳匹配简历……</Text>
        </Animated.View>
      </View>

      <View
        style={styles.cancelAction}
        onClick={onCancelGeneration}
        role='button'
        data-testid='analysis-cancel-action'
      >
        <Text style={styles.cancelActionMark}>×</Text>
        <Text style={styles.cancelActionText}>取消生成</Text>
      </View>
    </View>
  )
}

